import { render, screen } from '@testing-library/react';
import { describe, expect, it, vi, beforeEach } from 'vitest';
import Extrato from './Extrato.jsx';

const EXTRATO = {
  itens: [
    {
      atividadeId: 'atv_1',
      titulo: 'Palestra de abertura',
      tipo: 'palestra',
      cargaHorariaMinutos: 120,
      codigo: 'SA26-AAAA-BBBB',
    },
    {
      atividadeId: 'atv_2',
      titulo: 'Flutter do zero',
      tipo: 'minicurso',
      cargaHorariaMinutos: 360,
      codigo: null,
    },
  ],
  palestrasMinutos: 120,
  minicursosMinutos: 360,
  totalMinutos: 480,
  aproveitadoMinutos: 480,
};

function criarApiFalsa({ extrato = EXTRATO, erro } = {}) {
  return {
    obterExtrato: vi.fn(() => (erro ? Promise.reject(erro) : Promise.resolve(extrato))),
  };
}

describe('Extrato', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('lista atividades elegíveis com código ou indicação de ainda não emitido', async () => {
    const api = criarApiFalsa();
    render(<Extrato api={api} />);

    expect(await screen.findByText('Palestra de abertura')).toBeInTheDocument();
    expect(screen.getByText('SA26-AAAA-BBBB')).toBeInTheDocument();
    expect(screen.getByText('Flutter do zero')).toBeInTheDocument();
    expect(api.obterExtrato).toHaveBeenCalledTimes(1);
  });
});

import { useEffect, useState } from 'react';

export default function Extrato({ api }) {
  const [extrato, setExtrato] = useState(null);
  const [erro, setErro] = useState(null);

  useEffect(() => {
    setErro(null);
    setExtrato(null);
    api
      .obterExtrato()
      .then(setExtrato)
      .catch((erroDaApi) => setErro(erroDaApi));
  }, [api]);

  return (
    <section aria-label="Extrato de horas complementares">
      <h2>Extrato de Horas Complementares</h2>
      {erro && (
        <p role="alert">
          {erro.erro}: {erro.mensagem || erro.message}
        </p>
      )}
      {!erro && extrato === null && <p role="status">Carregando extrato...</p>}
      {!erro && extrato !== null && extrato.itens.length === 0 && (
        <p role="status">Nenhuma atividade elegível.</p>
      )}
      {!erro && extrato !== null && extrato.itens.length > 0 && (
        <ul>
          {extrato.itens.map((item) => (
            <li key={item.atividadeId} aria-label={item.titulo}>
              <p>{item.titulo}</p>
              <p>Tipo: {item.tipo}</p>
              <p>Carga horária: {item.cargaHorariaMinutos} min</p>
              {item.codigo ? <p>Código: {item.codigo}</p> : <p>Ainda não emitido</p>}
            </li>
          ))}
        </ul>
      )}
      {!erro && extrato !== null && (
        <div>
          <p>Palestras: {extrato.palestrasMinutos} min</p>
          <p>Minicursos: {extrato.minicursosMinutos} min</p>
          <p>Total: {extrato.totalMinutos} min</p>
          <p>Aproveitado: {extrato.aproveitadoMinutos} min</p>
        </div>
      )}
    </section>
  );
}

