import { render, screen, fireEvent } from '@testing-library/react';
import { describe, expect, it, vi, beforeEach } from 'vitest';
import VerificarCertificado from './VerificarCertificado.jsx';

const VERIFICACAO = {
  codigo: 'SA26-ABCD-EFGH',
  participante: 'Elisa F. da R.',
  atividade: 'Flutter do zero',
  cargaHorariaMinutos: 360,
  emitidoEm: '2026-10-20T12:00:00-03:00',
};

function criarApiFalsa({ verificacao = VERIFICACAO, erro } = {}) {
  return {
    verificarCertificado: vi.fn((codigo) =>
      erro ? Promise.reject(erro) : Promise.resolve(verificacao || { ...VERIFICACAO, codigo }),
    ),
  };
}

describe('VerificarCertificado', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('verifica o código digitado e mostra nome abreviado, atividade, carga e emissão', async () => {
    const api = criarApiFalsa();
    render(<VerificarCertificado api={api} />);

    fireEvent.change(screen.getByLabelText(/código do certificado/i), {
      target: { value: 'SA26-ABCD-EFGH' },
    });
    fireEvent.click(screen.getByRole('button', { name: /verificar/i }));

    expect(await screen.findByText('Elisa F. da R.')).toBeInTheDocument();
    expect(screen.getByText('Flutter do zero')).toBeInTheDocument();
    expect(api.verificarCertificado).toHaveBeenCalledWith('SA26-ABCD-EFGH');
  });
});

import { useState } from 'react';

export default function VerificarCertificado({ api }) {
  const [codigo, setCodigo] = useState('');
  const [verificacao, setVerificacao] = useState(null);
  const [erro, setErro] = useState(null);
  const [verificando, setVerificando] = useState(false);

  async function handleVerificar(evento) {
    evento.preventDefault();
    setErro(null);
    setVerificacao(null);
    setVerificando(true);
    try {
      const resposta = await api.verificarCertificado(codigo.trim());
      setVerificacao(resposta);
    } catch (erroDaApi) {
      setErro(erroDaApi);
    } finally {
      setVerificando(false);
    }
  }

  return (
    <section aria-label="Verificação pública de certificado">
      <h2>Verificar Certificado</h2>
      <form onSubmit={handleVerificar}>
        <label htmlFor="codigo-certificado">Código do certificado</label>
        <input
          id="codigo-certificado"
          value={codigo}
          onChange={(evento) => setCodigo(evento.target.value)}
          placeholder="SA26-XXXX-XXXX"
        />
        <button type="submit" disabled={verificando || codigo.trim() === ''}>
          Verificar
        </button>
      </form>
      {erro && (
        <p role="alert">
          {erro.erro}: {erro.mensagem || erro.message}
        </p>
      )}
      {verificacao && (
        <dl>
          <dt>Código</dt>
          <dd>{verificacao.codigo}</dd>
          <dt>Participante</dt>
          <dd>{verificacao.participante}</dd>
          <dt>Atividade</dt>
          <dd>{verificacao.atividade}</dd>
          <dt>Carga horária</dt>
          <dd>{verificacao.cargaHorariaMinutos} min</dd>
          <dt>Emitido em</dt>
          <dd>{verificacao.emitidoEm}</dd>
        </dl>
      )}
    </section>
  );
}

